@layer nz.tokens, nz.themes, nz.reset, nz.base, nz.components, nz.patterns, nz.utilities;


@layer nz.components {
  .nz-segmented-control {
    --_nz-segmented-control-height: var(--nz-size-control-md);
    --_nz-segmented-control-inset: var(--nz-space-1);
    --_nz-segmented-control-radius: var(--nz-radius-md);
    --_nz-segmented-control-item-padding-inline: var(--nz-space-3);
    --_nz-segmented-control-font: var(--nz-font-label-m);

    display: inline-flex;
    gap: var(--nz-segmented-control-gap, var(--nz-space-0-5));
    box-sizing: border-box;
    /* hugs its items: a stretching parent (a Field, a Stack column) must not widen the track */
    inline-size: fit-content;
    max-inline-size: 100%;
    block-size: var(--nz-segmented-control-height, var(--_nz-segmented-control-height));
    padding: var(--_nz-segmented-control-inset);
    border-radius: var(--nz-segmented-control-radius, var(--_nz-segmented-control-radius));
    background: var(--nz-segmented-control-bg, var(--nz-bg-subtle));
    font: var(--_nz-segmented-control-font);
    vertical-align: middle;

    &[data-full-width] {
      display: flex;
      inline-size: 100%;
    }

    &[data-invalid] {
      box-shadow: inset 0 0 0 var(--nz-border-width-default) var(--nz-border-critical);
    }
  }

  .nz-segmented-control[data-size='sm'] {
    --_nz-segmented-control-height: var(--nz-size-control-sm);
    --_nz-segmented-control-inset: var(--nz-space-0-5);
    --_nz-segmented-control-radius: var(--nz-radius-sm);
    --_nz-segmented-control-item-padding-inline: var(--nz-space-2);
  }

  .nz-segmented-control[data-size='lg'] {
    --_nz-segmented-control-height: var(--nz-size-control-lg);
    --_nz-segmented-control-item-padding-inline: var(--nz-space-4);
    --_nz-segmented-control-font: var(--nz-font-label-l);
  }

  .nz-segmented-control-item {
    position: relative;
    display: inline-flex;
    flex: none;
    align-items: center;
    justify-content: center;
    gap: var(--nz-space-1-5);
    box-sizing: border-box;
    min-inline-size: 0;
    padding-inline: var(--_nz-segmented-control-item-padding-inline);
    /* concentric with the track */
    border-radius: calc(
      var(--nz-segmented-control-radius, var(--_nz-segmented-control-radius)) -
        var(--_nz-segmented-control-inset)
    );
    color: var(--nz-segmented-control-fg, var(--nz-text-secondary));
    white-space: nowrap;
    cursor: pointer;
    user-select: none;
    transition:
      background-color var(--nz-duration-fast) var(--nz-easing-standard),
      box-shadow var(--nz-duration-fast) var(--nz-easing-standard),
      color var(--nz-duration-fast) var(--nz-easing-standard);

    @media (hover: hover) {
      &:hover:not(:has(> input:disabled)) {
        color: var(--nz-text-primary);
      }
    }

    /* The thumb. Against the track it is 1.04:1 (light) and 1.03:1 (dark), and Elevation/1 vanishes
       in dark, so a 1 px border/control ring and the Strong weight carry the selection (§15.3). */
    &:has(> input:checked) {
      background: var(--nz-segmented-control-thumb-bg, var(--nz-bg-surface));
      box-shadow:
        inset 0 0 0 var(--nz-border-width-default) var(--nz-border-control),
        var(--nz-elevation-1);
      color: var(--nz-segmented-control-fg-selected, var(--nz-text-primary));
    }

    /* a disabled group, item or fieldset */
    &:has(> input:disabled) {
      color: var(--nz-text-disabled);
      cursor: not-allowed;
    }

    &:has(> input:checked:disabled) {
      box-shadow: inset 0 0 0 var(--nz-border-width-default) var(--nz-border-subtle);
    }
  }

  /* The focus outline is nz.base's nested-input rule: :has(> input:focus-visible), or
     [data-focus-visible], which the item sets because WebKit matches no :focus-visible on a radio
     reached by an arrow key. */

  /* equal shares of the width, but never narrower than the item's own text */
  .nz-segmented-control[data-full-width] > .nz-segmented-control-item {
    flex: 1 1 0;
    min-inline-size: fit-content;
  }

  /* Hidden but in place: it takes focus (the outline lands on the item, nz.base) and anchors the
     browser's validation bubble. display: none would make it unfocusable. */
  .nz-segmented-control-input {
    position: absolute;
    inset: 0;
    margin: 0;
    opacity: 0;
    appearance: none;
    cursor: inherit;
  }

  .nz-segmented-control-icon {
    display: inline-flex;
    flex: none;
    inline-size: var(--nz-size-icon-sm);
    block-size: var(--nz-size-icon-sm);
    /* internal glyphs are 1em: size them to the slot */
    font-size: var(--nz-size-icon-sm);

    & > svg {
      inline-size: 100%;
      block-size: 100%;
    }
  }

  .nz-segmented-control-label {
    display: inline-grid;
    min-inline-size: 0;
  }

  .nz-segmented-control-text,
  .nz-segmented-control-sizer {
    grid-area: 1 / 1;
    overflow: hidden;
    text-overflow: ellipsis;
  }

  .nz-segmented-control-sizer,
  .nz-segmented-control-item:has(> input:checked) .nz-segmented-control-text {
    font-weight: var(--nz-font-label-m-strong-font-weight);
  }

  .nz-segmented-control-sizer {
    visibility: hidden;
  }

  @media (forced-colors: active) {
    /* the track's fill is dropped: an edge keeps the group visible; the selected item's outline is
       generated in nz.base from stateIndicator */
    .nz-segmented-control {
      outline: 1px solid CanvasText;
    }

    .nz-segmented-control-item:has(> input:disabled) {
      color: GrayText;
    }
  }

  /* Optical centring (M85, as Button's label): trimmed to cap height and baseline, padded back to
     one line, so the box keeps its height and the letters sit in its middle. */
  @supports (text-box: trim-both cap alphabetic) {
    .nz-segmented-control-text,
    .nz-segmented-control-sizer {
      padding-block: calc((1lh - 1cap) / 2);
      text-box: trim-both cap alphabetic;
    }
  }
}
